mapper.sql:
FROM announcement_attachment_policies p
        JOIN announcement_source_classification_rule_releases r ON r.id=p.rule_release_id

            p.policy_status_code=#{policyStatusCode}
            AND p.rule_release_id=#{ruleReleaseId}

mapper.select:
-- 큰 설정 JSON과 실행 경로는 목록에 포함하지 않는다. count와 같은 범위를 조회한다.
SELECT  
ORDER BY p.created_at DESC,p.id DESC LIMIT #{size} OFFSET #{offset}
